import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 10 Not for jazz","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 10 Not for jazz","description":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 被动语态与信息重点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 9 A cold welcome","link":"/life/english/new-concept/book-2/unit-01/lesson-009"},"next":{"text":"第二册：实践与进步 · Lesson 11 One good turn deserves another","link":"/life/english/new-concept/book-2/unit-01/lesson-011"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 9 A cold welcome","link":"/life/english/new-concept/book-2/unit-01/lesson-009"},"next":{"text":"第二册：实践与进步 · Lesson 11 One good turn deserves another","link":"/life/english/new-concept/book-2/unit-01/lesson-011"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-010.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-010.md"}'),o={name:"life/english/new-concept/book-2/unit-01/lesson-010.md"};function r(l,e,s,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-10-not-for-jazz" tabindex="-1">第二册：实践与进步 · Lesson 10 Not for jazz <a class="header-anchor" href="#第二册-实践与进步-·-lesson-10-not-for-jazz" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 10 Not for jazz&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>一把借来的旧吉他被维修后重新使用；练习将受损物品作为主语，说明发生了什么。本课的语言观察是：was repaired 的焦点是吉他；若要说明谁修的，再补 by a local technician。不能把 repaired 单独放在名词后当完整谓语。完成学习后，请用三句说明一件旧物的来源、损坏和修理结果。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>instrument</td><td>/ˈɪnstrəmənt/</td><td>n.</td><td>乐器；仪器</td><td>a musical instrument</td></tr><tr><td>repair</td><td>/rɪˈpeə/</td><td>v.</td><td>修理</td><td>repair a piano</td></tr><tr><td>damage</td><td>/ˈdæmɪdʒ/</td><td>n.</td><td>损坏</td><td>serious damage</td></tr><tr><td>string</td><td>/strɪŋ/</td><td>n.</td><td>弦；细绳</td><td>a guitar string</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be made of — 由……制成，强调材料可辨认</li><li>belong to — 属于，通常不用被动语态</li></ul><h2 id="语法讲解-被动语态与信息重点" tabindex="-1">语法讲解：被动语态与信息重点 <a class="header-anchor" href="#语法讲解-被动语态与信息重点" aria-label="Permalink to &quot;语法讲解：被动语态与信息重点&quot;">​</a></h2><p>被动语态由相应时态的 be 加过去分词构成，把动作的承受者放在主语位置。时态变化主要体现在 be 上，过去分词本身不随主语改变。只有可以带宾语的相关用法才能形成通常的被动句，happen、arrive 等不及物动词不能照搬。执行者未知、不重要或已经显然时可以省略 by 短语；需要追责或形成对比时则应保留。本课应用：was repaired 的焦点是吉他；若要说明谁修的，再补 by a local technician。不能把 repaired 单独放在名词后当完整谓语。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The old guitar was repaired by a local technician.</p></blockquote><p>那把旧吉他由一位当地技师修好了。</p><p>The old guitar 是承受动作的主语，was repaired 是一般过去时被动，by 短语指出执行者。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The guitar was belonged to me 错误；belong 表归属，用 The guitar belonged to me。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 guitar、repaired、technician；弱读 was 与 by，保留 repaired 的 /d/。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The old guitar was repaired by a local technician. One string had broken during practice. It now sounds clear again.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句说明一件旧物的来源、损坏和修理结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：The old guitar 是承受动作的主语，was repaired 是一般过去时被动，by 短语指出执行者。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The guitar was belonged to me 错误；belong 表归属，用 The guitar belonged to me。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 repair 的形式：The guitar was ___ yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repaired</p><p><strong>解析：</strong> 被动语态要求 be 加过去分词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>练习中坏了什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> One string broke.</p><p><strong>解析：</strong> 第二句说明一根弦断了，不能扩大为整把琴毁坏。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 A technician repaired the guitar 改为被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The guitar was repaired by a technician.</p><p><strong>解析：</strong> 宾语变主语，过去时通过 was 表达。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：被动语态与信息重点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-009">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-011">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(o,[["render",r]]);export{u as __pageData,b as default};
